import fs from 'node:fs';
import path from 'node:path';
import { spawn } from 'node:child_process';
import crypto from 'node:crypto';

export async function gate({ referenceDir, submissionDir }) {
  const secret = crypto.randomBytes(32).toString('hex');
  const id = crypto.randomBytes(16).toString('hex');
  const runnerPath = path.join(referenceDir, 'g-run-' + id + '.mjs');
  const resultPath = path.join(referenceDir, 'g-res-' + id + '.json');
  const configPath = path.join(referenceDir, 'g-cfg-' + id + '.json');
  const submissionPath = path.join(submissionDir, 'answer.mjs');

  const runnerSrc = [
    "import fs from 'node:fs';",
    "import { pathToFileURL } from 'node:url';",
    "const writeFileSync = fs.writeFileSync.bind(fs);",
    "const readFileSync = fs.readFileSync.bind(fs);",
    "const unlinkSync = fs.unlinkSync.bind(fs);",
    "const renameSync = fs.renameSync.bind(fs);",
    "const configPath = process.argv[2];",
    "const config = JSON.parse(readFileSync(configPath, 'utf8'));",
    "try { unlinkSync(configPath); } catch {}",
    "const secret = config.secret;",
    "const resultPath = config.resultPath;",
    "const submissionPath = config.submissionPath;",
    "function writeResult(payload) {",
    "  try {",
    "    const tmp = resultPath + '.tmp';",
    "    writeFileSync(tmp, JSON.stringify(Object.assign({ secret: secret }, payload)));",
    "    renameSync(tmp, resultPath);",
    "  } catch {}",
    "}",
    "let exitAttempt = false;",
    "process.exit = function () { exitAttempt = true; throw new Error('exit-blocked'); };",
    "process.abort = function () { exitAttempt = true; throw new Error('abort-blocked'); };",
    "function oracle(arr) {",
    "  const out = [];",
    "  for (let i = 0; i < arr.length; i++) {",
    "    if (i === 0 || arr[i] !== arr[i - 1]) out.push(arr[i]);",
    "  }",
    "  return out;",
    "}",
    "function eq(a, b) {",
    "  if (!Array.isArray(a) || !Array.isArray(b) || a.length !== b.length) return false;",
    "  for (let i = 0; i < a.length; i++) if (!Object.is(a[i], b[i])) return false;",
    "  return true;",
    "}",
    "function rng(seed) {",
    "  let s = seed >>> 0;",
    "  return function () { s = (Math.imul(s, 1664525) + 1013904223) >>> 0; return s / 4294967296; };",
    "}",
    "async function main() {",
    "  let dedupeSorted;",
    "  try {",
    "    const mod = await import(pathToFileURL(submissionPath).href);",
    "    dedupeSorted = mod.dedupeSorted;",
    "  } catch (e) {",
    "    writeResult({ ok: false, reason: 'import-failed' });",
    "    return;",
    "  }",
    "  if (typeof dedupeSorted !== 'function') {",
    "    writeResult({ ok: false, reason: 'missing-export' });",
    "    return;",
    "  }",
    "  const cases = [];",
    "  cases.push([]);",
    "  cases.push([5]);",
    "  cases.push([1, 2, 3]);",
    "  cases.push([4, 4, 4, 4]);",
    "  cases.push([1, 1, 2, 3]);",
    "  cases.push([1, 2, 3, 3]);",
    "  cases.push([-3, -3, -1, 0, 0, 2]);",
    "  cases.push(Array(40).fill(7));",
    "  cases.push(Array(100).fill(7));",
    "  cases.push(Array(40).fill(0).map(function (_, i) { return i; }));",
    "  cases.push([7, 7]);",
    "  cases.push([-10, -10, -10]);",
    "  cases.push([0, 0, 0, 1, 1, 2]);",
    "  cases.push(Array(41).fill(-3));",
    "  cases.push([1, 2, 2, 2, 2, 2, 3]);",
    "  cases.push(Array(64).fill(7));",
    "  cases.push(Array(32).fill(7));",
    "  cases.push(Array(33).fill(7));",
    "  cases.push(Array(20).fill(7).concat(Array(20).fill(8)));",
    "  cases.push(Array(40).fill(0));",
    "  const rand = rng(0xC0FFEE);",
    "  for (let t = 0; t < 120; t++) {",
    "    const len = 1 + Math.floor(rand() * 80);",
    "    const arr = [];",
    "    let v = Math.floor(rand() * 21) - 10;",
    "    for (let i = 0; i < len; i++) {",
    "      if (arr.length > 0 && rand() < 0.5) arr.push(arr[arr.length - 1]);",
    "      else { v += Math.floor(rand() * 3); arr.push(v); }",
    "    }",
    "    cases.push(arr);",
    "  }",
    "  for (let t = 0; t < 20; t++) {",
    "    const len = 1 + Math.floor(rand() * 10);",
    "    const arr = Array.from({ length: len }, function () { return Math.floor(rand() * 5) - 2; }).sort(function (a, b) { return a - b; });",
    "    cases.push(arr);",
    "  }",
    "  for (let i = 0; i < cases.length; i++) {",
    "    const input = cases[i].slice();",
    "    const expected = oracle(input);",
    "    let got;",
    "    try { got = dedupeSorted(input); } catch (e) {",
    "      writeResult({ ok: false, reason: 'threw on case ' + i, exitAttempt: exitAttempt });",
    "      return;",
    "    }",
    "    if (!eq(got, expected) || exitAttempt) {",
    "      writeResult({ ok: false, reason: 'failed case ' + i + ' len=' + input.length, exitAttempt: exitAttempt });",
    "      return;",
    "    }",
    "  }",
    "  writeResult({ ok: !exitAttempt, exitAttempt: exitAttempt, n: cases.length });",
    "}",
    "main().catch(function (e) { writeResult({ ok: false, reason: String(e) }); });",
  ].join('\n');

  fs.writeFileSync(runnerPath, runnerSrc, 'utf8');
  fs.writeFileSync(configPath, JSON.stringify({ secret: secret, resultPath: resultPath, submissionPath: submissionPath }), 'utf8');

  await new Promise(function (resolve) {
    const child = spawn(process.execPath, [runnerPath, configPath], {
      stdio: ['ignore', 'ignore', 'ignore'],
      cwd: referenceDir,
      env: {},
    });
    let done = false;
    const finish = function () {
      if (done) return;
      done = true;
      clearTimeout(timer);
      clearInterval(poll);
      try { child.kill('SIGKILL'); } catch (e) {}
      resolve();
    };
    const timer = setTimeout(finish, 20000);
    const poll = setInterval(function () {
      if (fs.existsSync(resultPath)) finish();
    }, 40);
    child.on('exit', finish);
    child.on('error', finish);
  });

  if (!fs.existsSync(resultPath)) {
    return { accept: false, reason: 'pinned suite did not run to completion' };
  }
  let parsed;
  try {
    parsed = JSON.parse(fs.readFileSync(resultPath, 'utf8'));
  } catch (e) {
    return { accept: false, reason: 'pinned suite did not run to completion' };
  }
  if (parsed.secret !== secret) {
    return { accept: false, reason: 'pinned suite did not run to completion' };
  }
  if (parsed.exitAttempt) {
    return { accept: false, reason: 'submission aborted the test process before the suite completed' };
  }
  if (parsed.ok !== true) {
    return { accept: false, reason: String(parsed.reason || 'pinned tests failed') };
  }
  return { accept: true, reason: 'all pinned tests passed' };
}

